import{_ as i,a as s,b as n,c as l,d as p,e as c,f as u,g as d,h as m,i as h,j as f,k as b,l as v,m as g,n as x,o as _,p as y,q as z,r as a,s as t,t as S,u as e,v as q,w as D,x as L,y as w,z as r,A as G,B as k,C,D as A}from"./chunks/DexShare.UQ90JY2f.js";import{_ as B}from"./chunks/DS-M6xx.Dx448PdS.js";import{_ as P}from"./chunks/UImenu.2mWyDoEW.js";import{_ as V}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as T,o as W,c as O,a3 as E}from"./chunks/framework.g9mfNVRQ.js";const Q=JSON.parse('{"title":"Source de données","description":"","frontmatter":{"source_hash":"32e9d6dee6","source_commit":"9eea450"},"headers":[],"relativePath":"fr/install/datasource.md","filePath":"fr/install/datasource.md"}'),N={name:"fr/install/datasource.md"};function U(F,o,M,j,I,R){return W(),O("div",null,[...o[0]||(o[0]=[E('<p>Tant qu&#39;aucune source de données de glycémie n&#39;est sélectionnée, xDrip affiche l&#39;assistant de source de données. Vous pouvez l&#39;activer ou le désactiver avec le <a href="./../use/mainUI.html#blood-drop-menu">menu goutte de sang</a>, puis le bouton de l&#39;assistant source.</p><img src="'+i+'" style="zoom:50%;"><p>Faites défiler jusqu&#39;à voir votre capteur ou votre cas d&#39;utilisation.</p><h2 id="g6-g7-1-1" tabindex="-1">G6, G7, 1, 1+ <a class="header-anchor" href="#g6-g7-1-1" aria-label="Permalink to &quot;G6, G7, 1, 1+ {#g6-g7-1-1}&quot;">​</a></h2><p>Si vous connectez xDrip directement à votre capteur (<a href="./g6.html">G6, G7, 1, 1+</a>), vous <strong>ne pourrez pas</strong> utiliser l&#39;application du fabricant ni envoyer les données vers Clarity (vous pouvez utiliser <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> ou <a href="./../use/cloud.html#tidepool">Tidepool</a>). Vous pourrez peut-être partager via les serveurs <a href="./../use/cloud.html#dex-share">Share</a>, mais cela doit d&#39;abord être configuré avec les applications du fabricant.</p><img src="'+s+'" style="zoom:50%;"><p>Si vous utilisez les applications du fabricant (G6, G7, 1+), vous pouvez connecter xDrip comme <a href="./dexshare.html">abonné Share</a>, à condition qu&#39;un abonné ait été configuré avec les applications du fabricant.</p><img src="'+n+'" style="zoom:50%;"><p>Avec <a href="./byod.html">BYODA</a> (G6 uniquement), si vous avez activé Broadcast to xDrip, vous n&#39;avez pas besoin de connexion réseau pour avoir les données dans xDrip. Utilisez la source de données Inter-app broadcast</p><img src="'+l+'" style="zoom:45%;"><p>Vous pouvez ajouter xDrip à votre configuration actuelle et sélectionner <a href="./companion.html">Companion app</a> pour que xDrip lise la glycémie dans les notifications de l&#39;application du fabricant (G6, G7, 1, 1+, Stelo). Notez qu&#39;avec l&#39;application du fabricant, Stelo donne une valeur toutes les 15 minutes.</p><img src="'+p+'" style="zoom:50%;"><p>C&#39;est aussi possible si vous utilisez <a href="./companion.html">CamAPS</a>, toujours avec la source de données Companion app</p><img src="'+c+'" style="zoom:50%;"><h2 id="libre" tabindex="-1">Libre <a class="header-anchor" href="#libre" aria-label="Permalink to &quot;Libre {#libre}&quot;">​</a></h2><p>xDrip se connecte directement aux Libre 2/2+ UE ; vous pouvez utiliser les Libre 1 et les 14 jours US avec un transmetteur. Les autres capteurs Libre 2 et 3 ne sont pas pris en charge directement.</p><p>Vous pouvez connecter un Libre 2/2+ UE à xDrip en ajoutant <a href="./../use/OOP.html">OOP2</a>. Vous <strong>ne pouvez pas</strong> utiliser l&#39;application du fabricant pour les alarmes (seulement pour les scans NFC) ni envoyer les données vers les serveurs du fabricant (utilisez <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> ou <a href="./../use/cloud.html#tidepool">Tidepool</a>). Utilisez la source de données <a href="./libreBT.html">Libre Bluetooth</a>.</p><img src="'+u+'" style="zoom:50%;"><p>Comme les Libre 1 n&#39;ont pas de Bluetooth, vous devez ajouter un <a href="./libreBT.html">transmetteur</a>. Utilisez la source de données <a href="./libreBT.html">Libre Bluetooth</a>.<br> Certains de ces transmetteurs fonctionnent aussi avec les Libre 2/2+ UE. Vérifiez que votre capteur ne nécessite pas d&#39;<a href="./../use/OOP.html">OOP</a>.</p><img src="'+d+'" style="zoom:50%;"><p>Depuis la version 2026.11.21, le groupe Libre propose aussi la source de données <a href="./li3.html">Li3</a>, qui connecte xDrip directement à un appareil Li3 par NFC et Bluetooth.</p><p>Pour les capteurs non pris en charge (Libre 2/2+ hors UE et Libre 3/3+), vous pouvez aussi utiliser Diabox ou Juggluco, puis <a href="./libre2patch.html">diffuser</a> les données vers xDrip, qui les recevra avec la source de données <a href="./libre2patch.html">Libre 2 patched</a> (et <strong>non</strong> l&#39;application patchée elle-même).</p><img src="'+m+'" style="zoom:50%;"><p>Vous pouvez suivre un CGM Libre 2/2+ ou un Libre 3/3+ avec xDrip grâce à la source de données <a href="./webfollower.html">Web follower</a>.</p><img src="'+h+'" style="zoom:50%;"><h2 id="guardian-and-minimed" tabindex="-1">Guardian et MiniMed <a class="header-anchor" href="#guardian-and-minimed" aria-label="Permalink to &quot;Guardian et MiniMed {#guardian-and-minimed}&quot;">​</a></h2><p>Avec une <a href="./640_670.html">pompe 640G/670G</a>, vous devez récupérer la glycémie depuis la pompe avec un lecteur de glycémie connecté à votre téléphone par un câble OTG.</p><img src="'+B+'" style="zoom:50%;"><p>Vous pouvez ajouter xDrip à votre configuration actuelle et sélectionner <a href="./companion.html">Companion app</a> pour que xDrip lise la glycémie dans les notifications de l&#39;application du fabricant.</p><img src="'+f+'" style="zoom:50%;"><p>Vous pouvez suivre les données du capteur partagées via <a href="./carelinkfollow.html">Carelink</a>, mais cette fonction peut être fréquemment cassée par le fabricant.</p><img src="'+b+'" style="zoom:50%;"><h2 id="aidex" tabindex="-1"><a href="./aidex.html">Aidex</a> <a class="header-anchor" href="#aidex" aria-label="Permalink to &quot;[Aidex](./aidex) {#aidex}&quot;">​</a></h2><p>Vous pouvez recevoir dans xDrip les données de l&#39;application du fabricant.</p><p>Vous pouvez ajouter xDrip à votre configuration actuelle et sélectionner <a href="./companion.html">Companion app</a> pour que xDrip lise la glycémie dans les notifications de l&#39;application du fabricant.</p><h2 id="sibionics" tabindex="-1">Sibionics <a class="header-anchor" href="#sibionics" aria-label="Permalink to &quot;Sibionics {#sibionics}&quot;">​</a></h2><p>L&#39;<a href="https://t.me/s/kubarev_modz" target="_blank" rel="noreferrer">application patchée</a> vous permet d&#39;utiliser xDrip avec la source de données <a href="./640_670.html">Inter-app broadcast</a>.</p><h2 id="caresens-air" tabindex="-1">CareSens Air <a class="header-anchor" href="#caresens-air" aria-label="Permalink to &quot;CareSens Air {#caresens-air}&quot;">​</a></h2><p>Vous pouvez recevoir dans xDrip les données de l&#39;application du fabricant avec la source de données <a href="./caresens.html">CareSens Air</a> (ou Inter-app broadcast).</p><img src="'+v+'" style="zoom:50%;"><br><h2 id="bluetooth-connection-to-a-sensor-or-a-bridge" tabindex="-1">Connexion Bluetooth à un capteur ou à un transmetteur <a class="header-anchor" href="#bluetooth-connection-to-a-sensor-or-a-bridge" aria-label="Permalink to &quot;Connexion Bluetooth à un capteur ou à un transmetteur {#bluetooth-connection-to-a-sensor-or-a-bridge}&quot;">​</a></h2><p>Lorsque vous connectez xDrip directement à un capteur, il gère lui-même la connexion Bluetooth, ou la connexion à l&#39;appareil Bluetooth qui envoie les données de votre capteur (appelé transmetteur).</p><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>N&#39;essayez <strong>PAS</strong> de vous connecter via Paramètres Android -&gt; Connexions -&gt; Bluetooth !</p></div><img src="'+g+'" style="zoom:100%;"><p>Si votre transmetteur est appairé à Android, dissociez-le avant de continuer.</p><img src="'+x+'" style="zoom:100%;"><div class="warning custom-block"><p class="custom-block-title">Un seul appareil à la fois</p><p>Les capteurs et les transmetteurs ne peuvent se connecter qu&#39;à un seul smartphone (ou tablette) à la fois, et à une seule application à la fois.<br> Vous devez désinstaller l&#39;application du fabricant pour connecter xDrip à votre capteur ou transmetteur.<br> Si un autre appareil est connecté à votre capteur ou transmetteur, éteignez-le ou désactivez l&#39;autre application avant d&#39;essayer de vous connecter avec xDrip.<br><strong>Vous ne pouvez pas vous connecter à deux téléphones ou applications. Sauf pour les Dex G6/G7/1 et 1+ : le second appareil ne peut être qu&#39;un récepteur/une pompe connectée ou une montre BlueJay.</strong></p></div><br><p>Vous devriez maintenant voir l&#39;assistant de sélection de la source de données.</p><img src="'+i+'" style="zoom:50%;"><p>Sinon, appuyez sur ce bouton pour afficher l&#39;assistant.</p><img src="'+_+'" style="zoom:75%;"><p>Si le bouton n&#39;est pas visible, vous pouvez l&#39;afficher par un appui long sur l&#39;icône xDrip, en activant <code>Bouton de l&#39;assistant source</code>.</p><img src="'+P+'" style="zoom:75%;"><br><h2 id="sensor-selection" tabindex="-1">Sélection du capteur <a class="header-anchor" href="#sensor-selection" aria-label="Permalink to &quot;Sélection du capteur {#sensor-selection}&quot;">​</a></h2><p>Les capteurs inutilisés et obsolètes ont été retirés de cette documentation.</p><h3 id="the-following-sensors-are-supported-directly-by-xdrip" tabindex="-1">Les capteurs suivants sont pris en charge directement par xDrip : <a class="header-anchor" href="#the-following-sensors-are-supported-directly-by-xdrip" aria-label="Permalink to &quot;Les capteurs suivants sont pris en charge directement par xDrip : {#the-following-sensors-are-supported-directly-by-xdrip}&quot;">​</a></h3><ul><li><a href="./g6.html">G6, G7, 1 et 1+</a><br><img src="'+y+'" style="zoom:54%;"> <img src="'+z+'" style="zoom:50%;"></li><li><a href="./libreBT.html">Libre (avec transmetteur)</a><br><img src="'+a+'" style="zoom:54%;"> <img src="'+t+'" style="zoom:50%;"></li><li>Libre avec montre SWR50 patchée<br><img src="'+a+'" style="zoom:54%;"> <img src="'+S+'" style="zoom:51%;"></li><li><a href="./libre2.html">Libre 2 (UE uniquement)</a><br><img src="'+a+'" style="zoom:54%;"> <img src="'+t+'" style="zoom:50%;"></li><li><a href="./medtrum.html">Medtrum A6</a><br><img src="'+e+'" style="zoom:54%;"> <img src="'+q+'" style="zoom:53%;"></li><li><a href="./caresens.html">CareSens Air</a><br><img src="'+e+'" style="zoom:52%;"> <img src="'+D+'" style="zoom:54%;"></li></ul><h3 id="the-following-sensors-and-features-are-supported-with-a-companion-app" tabindex="-1">Les capteurs et fonctions suivants sont pris en charge avec une application compagnon : <a class="header-anchor" href="#the-following-sensors-and-features-are-supported-with-a-companion-app" aria-label="Permalink to &quot;Les capteurs et fonctions suivants sont pris en charge avec une application compagnon : {#the-following-sensors-and-features-are-supported-with-a-companion-app}&quot;">​</a></h3><ul><li><a href="./libre2patch.html">Libre 2 (UE uniquement)</a><br><img src="'+a+'" style="zoom:51%;"> <img src="'+L+'" style="zoom:53%;"></li><li><a href="./eversense.html">Eversense</a><br><img src="'+e+'" style="zoom:52%;"> <img src="'+w+'" style="zoom:53%;"></li><li><a href="./640_670.html">Pompes 640G/670G</a><br><img src="'+e+'" style="zoom:52%;"> <img src="'+r+'" style="zoom:53%;"></li><li><a href="./byod.html">Build your own app (BYODA)</a> pour les capteurs G6<br><img src="'+e+'" style="zoom:52%;"> <img src="'+r+'" style="zoom:53%;"></li><li><a href="./aidex.html">Aidex</a><br><img src="'+G+'" style="zoom:53%;"></li><li><a href="./companion.html">Companion app</a> pour G6, G7, 1, 1+, CamAPS et Eversense<br> Voir ci-dessous.</li></ul><br><h2 id="follower-mode" tabindex="-1">Mode abonné <a class="header-anchor" href="#follower-mode" aria-label="Permalink to &quot;Mode abonné {#follower-mode}&quot;">​</a></h2><ul><li><a href="./xdripfollower.html">xDrip Sync</a> (nécessite les Services Google Play)<br><img src="'+k+'" style="zoom:53%;"></li><li><a href="./nightscoutfollower.html">Nightscout</a><br><img src="'+e+'" style="zoom:52%;"> <img src="'+C+'" style="zoom:53%;"></li><li><a href="./dexshare.html">Dex Share</a><br><img src="'+e+'" style="zoom:52%;"> <img src="'+A+'" style="zoom:53%;"></li><li><a href="./webfollower.html">Libre Web Follower</a><br> Voir ci-dessous.</li><li><a href="./carelinkfollow.html">CareLink Follower</a><br> Voir ci-dessous.</li></ul><br><h2 id="changing-data-source" tabindex="-1">Changer de source de données <a class="header-anchor" href="#changing-data-source" aria-label="Permalink to &quot;Changer de source de données {#changing-data-source}&quot;">​</a></h2><p>Vous pouvez sélectionner une autre source de données sans passer par l&#39;assistant, depuis le menu des paramètres :</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+V+'" style="zoom:75%;"></p><p> Paramètres<br>  Source de données matérielle</p></div><p><a href="./g6.html">G6, G7, 1 et 1+</a></p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> Dex<span style="float:right;">○ </span>   </p></div><p><a href="./libreBT.html">Libre (avec transmetteur)</a></p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> Libre Bluetooth<span style="float:right;">○ </span>   </p></div><p><a href="https://github.com/tzachi-dar/LibreAllHouse" target="_blank" rel="noreferrer">Libre whole house</a></p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> Libre Bluetooth + wifi<span style="float:right;">○ </span>   <br>  Libre wifi<span style="float:right;">○ </span>   </p></div><p><a href="./xdripfollower.html">xDrip Sync</a></p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> xDrip+ Sync Follower<span style="float:right;">○ </span>   </p></div><p>Libre avec montre SWR50 patchée</p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> LibreAlarm<span style="float:right;">○ </span>   </p></div><p><a href="./libre2patch.html">Libre 2 (UE uniquement), Diabox ou Juggluco</a></p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> Libre (patched App)<span style="float:right;">○ </span>   </p></div><p><a href="./640_670.html">Pompes 640G/670G</a>, <a href="./eversense.html">Eversense</a> et <a href="./byod.html">Build your own app (BYODA)</a></p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> Inter-app broadcast<span style="float:right;">○ </span>   </p></div><p>Cette source de données s&#39;appelait « 640G / EverSense » avant la version 2026.09.04.</p><p><a href="./medtrum.html">Medtrum A6/S7</a></p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> Medtrum A6<span style="float:right;">○ </span>   </p></div><p><a href="./nightscoutfollower.html">Nightscout</a></p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> Nightscout Follower<span style="float:right;">○ </span>   </p></div><p><a href="./dexshare.html">Dex Share</a></p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> Dex Share Follower<span style="float:right;">○ </span>   </p></div><p><a href="./companion.html">Companion app</a> pour G6, G7, One et CamAPS</p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> Companion App<span style="float:right;">○ </span>   </p></div><p><a href="./smartguide.html">SmartGuide</a></p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> SmartGuide<span style="float:right;">○ </span>   </p></div><p><a href="./aidex.html">GlucoRx/Aidex</a></p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> GlucoRx/Aidex App<span style="float:right;">○ </span>   </p></div><p><a href="./webfollower.html">Web Follower</a> pour Libre 2 CGM et Libre 3</p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> Web Follower<span style="float:right;">○ </span>   </p></div><p><a href="./carelinkfollow.html">CareLink</a></p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> CareLink Follower<span style="float:right;">○ </span>   </p></div><h5 id="disable-collection" tabindex="-1">Désactiver la collection de données <a class="header-anchor" href="#disable-collection" aria-label="Permalink to &quot;Désactiver la collection de données {#disable-collection}&quot;">​</a></h5><p>Si vous voulez désactiver xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Source de données matérielle</p><p> Désactiver la collection de données<span style="float:right;">○ </span>   </p></div><br><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>La liste <code>Source de données matérielle</code> contient aussi <code>Bluetooth Wixel</code>, <code>xBridge Wixel</code>, <code>Wifi Wixel</code>, <code>Wifi Wixel + BT Wixel</code> et <code>Wifi Wixel + xBridge Wixel</code> : ce sont des entrées anciennes/obsolètes qui ne sont pas traitées dans cette documentation.</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 22/11/2026</em></a></p>',107)])])}const X=T(N,[["render",U]]);export{Q as __pageData,X as default};
